fn print_help() {
    println!("Interact with the Pueue daemon");
    println!();
    println!("Use the `--help` long form to get detailed help output on each subcommand!");
    println!();
    println!("Usage: executable [OPTIONS] [COMMAND]");
    println!();
    println!("Commands:");
    println!("  add          Enqueue a task for execution");
    println!("  remove       Remove tasks from the list. Running or paused tasks need to be killed first");
    println!("  switch       Switches the queue position of two commands");
    println!("  stash        Stash a task. Stashed tasks won't be automatically started");
    println!("  enqueue      Enqueue stashed tasks. They'll be handled normally afterwards");
    println!("  start        Resume operation of specific tasks or groups of tasks");
    println!("  restart      Restart failed or successful task(s)");
    println!("  pause        Either pause running tasks or specific groups of tasks");
    println!("  kill         Kill specific running tasks or whole task groups");
    println!("  send         Send something to a task. Useful for sending confirmations such as 'y\\n'");
    println!("  edit         Adjust editable properties of a task");
    println!("  env          Use this to add or remove environment variables from tasks");
    println!("  group        Use this to add or remove groups");
    println!("  status       Display the current status of all tasks");
    println!("  log          Display the log output of finished tasks");
    println!("  follow       Follow the output of a currently running task. This command works like \"tail -f\"");
    println!("  wait         Wait until tasks are finished");
    println!("  clean        Remove all finished tasks from the list");
    println!("  reset        Kill all tasks, clean up afterwards and reset EVERYTHING!");
    println!("  shutdown     Remotely shut down the daemon. Should only be used if the daemon isn't started by a");
    println!("               service manager");
    println!("  parallel     Set the amount of allowed parallel tasks");
    println!("  completions  Generates shell completion files");
    println!("  help         Print this message or the help of the given subcommand(s)");
    println!();
    println!("Options:");
    println!("  -v, --verbose...");
    println!("          Verbose mode (-v, -vv, -vvv)");
