fn print_add_help() {
    println!("Enqueue a task for execution.");
    println!();
    println!("There're many different options when scheduling a task. Check the individual option help texts for");
    println!("more information. Furthermore, please remember that scheduled commands are executed via your system");
    println!("shell. This means that the command needs proper shell escaping. The safest way to preserve shell");
    println!("escaping is to surround your command with quotes, for example:");
    println!();
    println!("pueue add 'ls $HOME && echo \"Some string\"'");
    println!();
    println!("Usage: executable add [OPTIONS] <COMMAND>...");
    println!();
    println!("Arguments:");
    println!("  <COMMAND>...");
    println!("          The command to be added");
    println!();
    println!("Options:");
    println!("  -w, --working-directory <working-directory>");
    println!("          Specify current working directory");
    println!();
    println!("  -e, --escape");
    println!("          Escape any special shell characters (\" \", \"&\", \"!\", etc.).");
    println!("          Beware: This implicitly disables nearly all shell specific syntax (\"&&\", \"&>\").");
    println!();
    println!("  -i, --immediate");
    println!("          Immediately start the task");
    println!();
    println!("      --follow");
    println!("          Immediately follow a task, if it's started with --immediate");
    println!();
    println!("  -s, --stashed");
    println!("          Create the task in Stashed state.");
    println!("          ");
    println!("          Useful to avoid immediate execution if the queue is empty.");
    println!();
    println!("  -d, --delay <delay>");
    println!("          Prevents the task from being enqueued until 'delay' elapses. See \"enqueue\" for accepted");
    println!("          formats");
    println!();
    println!("  -g, --group <GROUP>");
    println!("          Assign the task to a group.");
    println!("          ");
    println!("          Groups kind of act as separate queues. All groups run in parallel and you can specify the");
    println!("          amount of parallel tasks for each group. If no group is specified, the default group will");
    println!("          be used.");
    println!("          ");
    println!("          Create groups via the `pueue group` subcommand");
    println!();
    println!("  -a, --after <after>...");
    println!("          Start the task once all specified tasks have successfully finished.");
    println!("          ");
    println!("          As soon as one of the dependencies fails, this task will fail as well.");
    println!();
    println!("  -o, --priority <PRIORITY>");
    println!("          Start this task with a higher priority.");
    println!("          ");
    println!("          The higher the number, the faster it will be processed.");
    println!();
    println!("  -l, --label <LABEL>");
    println!("          Add some information for yourself.");
    println!("          ");
    println!("          This string will be shown in the \"status\" table. There's no additional logic connected to");
    println!("          it.");
    println!();
    println!("  -p, --print-task-id");
    println!("          Only return the task id instead of a text.");
    println!("          ");
    println!("          This is useful when working with dependencies in scripts.");
    println!();
    println!("  -h, --help");
    println!("          Print help (see a summary with '-h')");
}

